import{_ as l,a0 as p,w as d,s as c,ao as t,I as i,x as n,a1 as e,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"chown 命令簡介 | LCTT x X-CMD","titleTemplate":false,"description":"chown 命令簡介 | LCTT (201910) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"chown 命令簡介 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"chown 命令簡介 | LCTT (201910) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201910/20190826 Introduction to the Linux chown command","title":"chown 命令簡介","tag":"201910","desc":""},"relativePath":"201910/20190826 Introduction to the Linux chown command.md","filePath":"[post].md"}'),r={name:"201910/20190826 Introduction to the Linux chown command.md"};function h(u,s,g,k,m,b){const a=p("Link");return d(),c("div",null,[s[20]||(s[20]=t(`<h1 id="chown-命令簡介" tabindex="-1">chown 命令簡介 <a class="header-anchor" href="#chown-命令簡介" aria-label="Permalink to “chown 命令簡介”">​</a></h1><blockquote><p>學習如何使用 chown 命令更改文件或目錄的所有權。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/201910/03/000014mfrxrxi5rej75mjs.jpg" alt=""></p><p>Linux 系統上的每個文件和目錄均由某個人擁有，擁有者可以完全控制更改或刪除他們擁有的文件。除了有一個<em>擁有用户</em>外，文件還有一個<em>擁有組</em>。</p><p>你可以使用 <code>ls -l</code> 命令查看文件的所有權：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[pablo@workstation Downloads]$ ls -l</span></span>
<span class="line"><span>total 2454732</span></span>
<span class="line"><span>-rw-r--r--. 1 pablo pablo 1934753792 Jul 25 18:49 Fedora-Workstation-Live-x86_64-30-1.2.iso</span></span></code></pre></div><p>該輸出的第三和第四列是擁有用户和組，它們一起稱為<em>所有權</em>。上面的那個 ISO 文件這兩者都是 <code>pablo</code>。</p>`,7)),i("p",null,[s[1]||(s[1]=n("所有權設置由 ",-1)),e(a,{href:"https://opensource.com/article/19/8/introduction-linux-chmod-command"},{default:o(()=>[...s[0]||(s[0]=[n("chmod 命令",-1)])]),_:1}),s[2]||(s[2]=n("進行設置，控制允許誰可以執行讀取、寫入或運行的操作。你可以使用 ",-1)),s[3]||(s[3]=i("code",null,"chown",-1)),s[4]||(s[4]=n(" 命令更改所有權（一個或兩者）。",-1))]),s[21]||(s[21]=t(`<p>所有權經常需要更改。文件和目錄一直存在在系統中，但用户不斷變來變去。當文件和目錄在系統中移動時，或從一個系統移動到另一個系統時，所有權也可能需要更改。</p><p>我的主目錄中的文件和目錄的所有權是我的用户和我的主要組，以 <code>user:group</code> 的形式表示。假設 Susan 正在管理 Delta 組，該組需要編輯一個名為 <code>mynotes</code> 的文件。你可以使用 <code>chown</code> 命令將該文件的用户更改為 <code>susan</code>，組更改為 <code>delta</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chown susan:delta mynotes</span></span>
<span class="line"><span>ls -l</span></span>
<span class="line"><span>-rw-rw-r--. 1 susan delta 0 Aug  1 12:04 mynotes</span></span></code></pre></div><p>當給該文件設置好了 Delta 組時，它可以分配回給我：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chown alan mynotes</span></span>
<span class="line"><span>$ ls -l mynotes</span></span>
<span class="line"><span>-rw-rw-r--. 1 alan delta 0 Aug  1 12:04 mynotes</span></span></code></pre></div><p>給用户後添加冒號（<code>:</code>），可以將用户和組都分配回給我：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chown alan: mynotes</span></span>
<span class="line"><span>$ ls -l mynotes</span></span>
<span class="line"><span>-rw-rw-r--. 1 alan alan 0 Aug  1 12:04 mynotes</span></span></code></pre></div><p>通過在組前面加一個冒號，可以只更改組。現在，<code>gamma</code> 組的成員可以編輯該文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chown :gamma mynotes</span></span>
<span class="line"><span>$ ls -l</span></span>
<span class="line"><span>-rw-rw-r--. 1 alan gamma 0 Aug  1 12:04 mynotes</span></span></code></pre></div><p><code>chown</code> 的一些附加參數都能用在命令列和腳本中。就像許多其他 Linux 命令一樣，<code>chown</code> 有一個遞歸參數（<code>-R</code>），它告訴該命令進入目錄以對其中的所有文件進行操作。沒有 <code>-R</code> 標誌，你就只能更改文件夾的權限，而不會更改其中的文件。在此示例中，假定目的是更改目錄及其所有內容的權限。這裏我添加了 <code>-v</code>（詳細）參數，以便 <code>chown</code> 報告其工作情況：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l . conf</span></span>
<span class="line"><span>.:</span></span>
<span class="line"><span>drwxrwxr-x 2 alan alan 4096 Aug  5 15:33 conf</span></span>
<span class="line"><span></span></span>
<span class="line"><span>conf:</span></span>
<span class="line"><span>-rw-rw-r-- 1 alan alan 0 Aug  5 15:33 conf.xml</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ chown -vR susan:delta conf</span></span>
<span class="line"><span>changed ownership of &#39;conf/conf.xml&#39; from alan:alan to  susan:delta</span></span>
<span class="line"><span>changed ownership of &#39;conf&#39; from alan:alan to  susan:delta</span></span></code></pre></div><p>根據你的角色，你可能需要使用 <code>sudo</code> 來更改文件的所有權。</p><p>在更改文件的所有權以匹配特定配置時，或者在你不知道所有權時（例如運行腳本時），可以使用參考文件（<code>--reference=RFILE</code>）。例如，你可以複製另一個文件（<code>RFILE</code>，稱為參考文件）的用户和組，以撤消上面所做的更改。回想一下，點（<code>.</code>）表示當前的工作目錄。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chown -vR --reference=. conf</span></span></code></pre></div><h3 id="報告更改" tabindex="-1">報告更改 <a class="header-anchor" href="#報告更改" aria-label="Permalink to “報告更改”">​</a></h3><p>大多數命令都有用於控制其輸出的參數。最常見的是 <code>-v</code>（<code>--verbose</code>）以啓用詳細信息，但是 <code>chown</code> 還具有 <code>-c</code>（<code>--changes</code>）參數來指示 <code>chown</code> 僅在進行更改時報告。<code>chown</code> 還會報告其他情況，例如不允許進行的操作。</p><p>參數 <code>-f</code>（<code>--silent</code>、<code>--quiet</code>）用於禁止顯示大多數錯誤消息。在下一節中，我將使用 <code>-f</code> 和 <code>-c</code>，以便僅顯示實際更改。</p><h3 id="保持根目錄" tabindex="-1">保持根目錄 <a class="header-anchor" href="#保持根目錄" aria-label="Permalink to “保持根目錄”">​</a></h3><p>Linux 文件系統的根目錄（<code>/</code>）應該受到高度重視。如果命令在此層級上犯了一個錯誤，則後果可能會使系統完全無用。尤其是在運行一個會遞歸修改甚至刪除的命令時。<code>chown</code> 命令具有一個可用於保護和保持根目錄的參數，它是 <code>--preserve-root</code>。如果在根目錄中將此參數和遞歸一起使用，那麼什麼也不會發生，而是會出現一條消息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chown -cfR --preserve-root alan /</span></span>
<span class="line"><span>chown: it is dangerous to operate recursively on &#39;/&#39;</span></span>
<span class="line"><span>chown: use --no-preserve-root to override this failsafe</span></span></code></pre></div><p>如果不與 <code>--recursive</code> 結合使用，則該選項無效。但是，如果該命令由 <code>root</code> 用户運行，則 <code>/</code> 本身的權限將被更改，但其下的其他文件或目錄的權限則不會更改：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chown -c --preserve-root alan /</span></span>
<span class="line"><span>chown: changing ownership of &#39;/&#39;: Operation not permitted</span></span>
<span class="line"><span>[root@localhost /]# chown -c --preserve-root alan /</span></span>
<span class="line"><span>changed ownership of &#39;/&#39; from root to alan</span></span></code></pre></div><h3 id="所有權即安全" tabindex="-1">所有權即安全 <a class="header-anchor" href="#所有權即安全" aria-label="Permalink to “所有權即安全”">​</a></h3><p>文件和目錄所有權是良好的信息安全性的一部分，因此，偶爾檢查和維護文件所有權以防止不必要的訪問非常重要。<code>chown</code> 命令是 Linux 安全命令集中最常見和最重要的命令之一。</p><hr>`,25)),i("p",null,[s[6]||(s[6]=n("via: ",-1)),e(a,{href:"https://opensource.com/article/19/8/linux-chown-command"},{default:o(()=>[...s[5]||(s[5]=[n("https://opensource.com/article/19/8/linux-chown-command",-1)])]),_:1})]),i("p",null,[s[11]||(s[11]=n("作者：",-1)),e(a,{href:"https://opensource.com/users/alanfdoss"},{default:o(()=>[...s[7]||(s[7]=[n("Alan Formy-Duval",-1)])]),_:1}),s[12]||(s[12]=n(" 選題：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:o(()=>[...s[8]||(s[8]=[n("lujun9972",-1)])]),_:1}),s[13]||(s[13]=n(" 譯者：",-1)),e(a,{href:"https://github.com/wxy"},{default:o(()=>[...s[9]||(s[9]=[n("wxy",-1)])]),_:1}),s[14]||(s[14]=n(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:o(()=>[...s[10]||(s[10]=[n("wxy",-1)])]),_:1})]),i("p",null,[s[17]||(s[17]=n("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...s[15]||(s[15]=[n("LCTT",-1)])]),_:1}),s[18]||(s[18]=n(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:o(()=>[...s[16]||(s[16]=[n("Linux中國",-1)])]),_:1}),s[19]||(s[19]=n(" 榮譽推出",-1))])])}const y=l(r,[["render",h]]);export{x as __pageData,y as default};
